use std::env;
use std::fs;
use std::path::Path;
use walkdir::WalkDir;
use regex::Regex;

fn main() {
    // Note: This build script synthesizes trimmed `pub mod` entries for a set
    // of upstream crates and writes them to `embedded_mods.rs` in `OUT_DIR`.
    // The generated file is then `include!`d by `src/lib.rs` at build time.
    //
    // See [build metad-programming docs](docs/build-meta.md) for maintenance guidance, IDE notes, and
    // troubleshooting steps when upstream sources move or change.
    println!("cargo:rerun-if-changed=brush-fork");
    println!("cargo:rerun-if-changed=coreutils-fork");
    println!("cargo:rerun-if-changed=build.rs");

    let out_dir = env::var("OUT_DIR").unwrap();
    let out_path = Path::new(&out_dir);

    // Generate stub embedded_locales.rs for uucore
    let locales_path = out_path.join("embedded_locales.rs");
    fs::write(locales_path, r#"
pub fn get_embedded_locale(_key: &str) -> Option<&'static str> {
    None
}
"#).unwrap();

    // Define mappings: Source Dir -> Dest Dir Name
    let mappings = vec![
        ("brush-fork/brush-core", "brush-core"),
        ("brush-fork/brush-builtins", "brush-builtins"),
        ("brush-fork/brush-parser", "brush-parser"),
        ("brush-fork/brush-interactive", "brush-interactive"),
        ("brush-fork/brush-shell", "brush-shell"),
        ("coreutils-fork/src/uucore", "uucore"),
    ];

    // Generate a small file that exposes the transformed crates as modules.
    // This centralizes the `pub mod` includes so `src/lib.rs` stays minimal.
    // The generated file contains doc comments pointing back to the original
    // source paths to aid IDE tooltips and human readers. See
    // `docs/embedded_mods.md` for full maintenance instructions.
    let mut mods = String::new();
    mods.push_str("// Auto-generated by build.rs - do not edit.\n");
    mods.push_str("// Exposes transformed crates from OUT_DIR\n");
    mods.push_str("// See docs/embedded_mods.md for details and maintenance.\n\n");
    for (src, dest_name) in &mappings {
        // Validate mapping paths early to give a helpful error if upstream
        // sources are missing or moved.
        if !Path::new(src).exists() {
            panic!("Expected mapped source path '{}' to exist; update `mappings` in build.rs or fetch it.", src);
        }

        // Trigger rebuild if the source subtree changes.
        println!("cargo:rerun-if-changed={}", src);
        let module_name = dest_name.replace('-', "_");
        let include_path = if *dest_name == "uucore" {
            format!("{}/src/lib/lib.rs", dest_name)
        } else {
            format!("{}/src/lib.rs", dest_name)
        };

        // Add a doc comment indicating the original source path so IDEs and humans
        // can see where the transformed code came from.
        mods.push_str(&format!("/// Source: {}\n", src));
        mods.push_str(&format!(
            "pub mod {name} {{ include!(concat!(env!(\"OUT_DIR\"), \"/{path}\")); }}\n\n",
            name = module_name,
            path = include_path
        ));
    }

    let mods_path = out_path.join("embedded_mods.rs");
    fs::write(mods_path, mods).unwrap();

    for (src, dest_name) in mappings {
        let src_path = Path::new(src).join("src");
        let dest_path = out_path.join(dest_name).join("src");

        if dest_path.exists() {
            fs::remove_dir_all(&dest_path).unwrap();
        }
        fs::create_dir_all(dest_path.parent().unwrap()).unwrap();

        // Copy directory
        let mut options = fs_extra::dir::CopyOptions::new();
        options.overwrite = true;
        options.copy_inside = true;
        
        if let Err(e) = fs_extra::dir::copy(&src_path, dest_path.parent().unwrap(), &options) {
            eprintln!("Failed to copy {:?} to {:?}: {}", src_path, dest_path.parent().unwrap(), e);
            panic!("Failed to copy source");
        }

        // Inject wasm_interactive.rs if we are processing brush-interactive
        if dest_name == "brush-interactive" {
            let wasm_interactive_src = Path::new("src/wasm_interactive.rs");
            let wasm_interactive_dest = dest_path.join("wasm_interactive.rs");
            if wasm_interactive_src.exists() {
                fs::copy(wasm_interactive_src, wasm_interactive_dest).unwrap();
                
                // Also copy bridge.js so include_str! works
                let bridge_src = Path::new("src/tty/bridge.js");
                let bridge_dest = dest_path.join("tty/bridge.js");
                if bridge_src.exists() {
                    fs::create_dir_all(bridge_dest.parent().unwrap()).unwrap();
                    fs::copy(bridge_src, bridge_dest).unwrap();
                }
            }
        }

        // Patch files
        patch_files(&dest_path);

        // Create embedded.rs for brush-shell
        if dest_name == "brush-shell" {
            let embedded_path = dest_path.join("embedded.rs");
            fs::write(embedded_path, r#"
use crate::brush_shell::args::CommandLineArgs;
use crate::brush_shell::entry;
use std::collections::HashMap;

pub fn run_custom(
    args: Vec<String>,
    extra_builtins: impl FnOnce(&mut HashMap<String, crate::brush_core::builtins::Registration>),
) {
    let parsed_args = match CommandLineArgs::try_parse_from(args.iter().cloned()) {
        Ok(a) => a,
        Err(e) => {
            let _ = e.print();
            return;
        }
    };
    
    // Register extra builtins in global registry
    unsafe {
        let mut builtin_map = HashMap::new();
        extra_builtins(&mut builtin_map);
        entry::EXTRA_BUILTINS = Some(builtin_map);
    }
    
    println!("Spawning run_async");
    crate::wasm_async::spawn(async move {
        println!("run_async started");
        let _ = entry::run_async(args, parsed_args).await;
        println!("run_async finished");
    });
    println!("Ticking runtime");
    crate::wasm_async::tick();
    println!("Tick returned");
}
"#).unwrap();
        }
    }
}

fn patch_files(dir: &Path) {
    let crates = vec![
        "brush_core",
        "brush_builtins",
        "brush_parser",
        "brush_interactive",
        "brush_shell",
        "uucore",
    ];

    // Regex for `use CRATE`
    // Matches `use ` followed by CRATE followed by word boundary
    let use_pattern = format!(r"use\s+({})\b", crates.join("|"));
    let use_re = Regex::new(&use_pattern).unwrap();

    // Regex for `CRATE::`
    // Matches (start or non-colon) followed by CRATE followed by ::
    let path_pattern = format!(r"([^:]|^)\b({})::", crates.join("|"));
    let path_re = Regex::new(&path_pattern).unwrap();

    // Regex for inner doc comments `//!`
    let doc_re = Regex::new(r"(?m)^//!").unwrap();

    // Regex for inner attributes `#![...]`
    let inner_attr_re = Regex::new(r"(?m)^#\!\[.*\]").unwrap();

    for entry in WalkDir::new(dir) {
        let entry = entry.unwrap();
        if entry.file_type().is_file() && entry.path().extension().map_or(false, |e| e == "rs") {
            let path = entry.path();
            let content = fs::read_to_string(path).unwrap();
            let mut new_content = content.clone();

            // Specific file patches (run early to avoid conflicts with general patches)
            if path.to_string_lossy().ends_with("brush-interactive/src/lib.rs") {
                // Disable original modules/exports to avoid conflicts
                // Comment out cfg attributes for backends
                let cfg_re = Regex::new(r#"(?m)^#\[cfg\(feature = "(reedline|basic|minimal)"\)\]"#).unwrap();
                new_content = cfg_re.replace_all(&new_content, "// $0").to_string();

                // Comment out mod declarations
                let mod_re = Regex::new(r"(?m)^(pub\s+)?mod\s+(reedline|basic|minimal)\s*;").unwrap();
                new_content = mod_re.replace_all(&new_content, "// $0").to_string();

                // Comment out pub use declarations
                let use_re = Regex::new(r"(?m)^pub\s+use\s+(reedline|basic|minimal)::.*").unwrap();
                new_content = use_re.replace_all(&new_content, "// $0").to_string();

                new_content.push_str("\npub mod wasm_interactive;");
                new_content.push_str("\npub use wasm_interactive::{WasmInputBackend, ReedlineInputBackend, BasicInputBackend, MinimalInputBackend};");
                
                // Inline refs module to avoid resolution issues
                let refs_re = Regex::new(r"(?m)^mod\s+refs\s*;").unwrap();
                if refs_re.is_match(&new_content) {
                    println!("cargo:warning=Inlining refs module");
                    new_content = refs_re.replace(&new_content, r#"
pub type ShellRef = std::sync::Arc<tokio::sync::Mutex<super::brush_core::Shell>>;
"#).to_string();
                } else {
                    println!("cargo:warning=Could not find 'mod refs;' to inline");
                }
                
                // Remove pub use refs::ShellRef; since we defined it directly
                let use_refs_re = Regex::new(r"(?m)^pub\s+use\s+refs::ShellRef\s*;").unwrap();
                new_content = use_refs_re.replace_all(&new_content, "// $0").to_string();
            }

            // 0. Replace `crate::` with `crate::CURRENT_CRATE::`
            // Identify which "crate" this file belongs to
            let path_str = path.to_string_lossy();
            let current_crate = if path_str.contains("/brush-parser/") { Some("brush_parser") }
                else if path_str.contains("/brush-core/") { Some("brush_core") }
                else if path_str.contains("/brush-builtins/") { Some("brush_builtins") }
                else if path_str.contains("/brush-interactive/") { Some("brush_interactive") }
                else if path_str.contains("/brush-shell/") { Some("brush_shell") }
                else if path_str.contains("/uucore/") { Some("uucore") }
                else { None };

            if let Some(c_name) = current_crate {
                // Replace `crate::` with `crate::c_name::`
                // But avoid `pub(crate)` which doesn't have `::`
                // Regex: `\bcrate::`
                let crate_re = Regex::new(r"\bcrate::").unwrap();
                new_content = crate_re.replace_all(&new_content, format!("crate::{}::", c_name).as_str()).to_string();
            }

            // 1. Replace `//!` with `//`
            new_content = doc_re.replace_all(&new_content, "//").to_string();

            // 1.5 Replace `#![...]` with `// #![...]`
            new_content = inner_attr_re.replace_all(&new_content, "// $0").to_string();

            // 2. Replace `use CRATE` with `use crate::CRATE`
            new_content = use_re.replace_all(&new_content, |caps: &regex::Captures| {
                format!("use crate::{}", &caps[1])
            }).to_string();

            // 3. Replace `CRATE::` with `crate::CRATE::` (if not preceded by :)
            new_content = path_re.replace_all(&new_content, |caps: &regex::Captures| {
                format!("{}crate::{}::", &caps[1], &caps[2])
            }).to_string();

            // Patch: Redirect crossterm to our local shim
            new_content = new_content.replace("crossterm::", "crate::tty::crossterm_shim::");
            new_content = new_content.replace("use crossterm;", "use crate::tty::crossterm_shim as crossterm;");
            new_content = new_content.replace("use crossterm ", "use crate::tty::crossterm_shim ");

            // 4. Special case: Disable conflicting blanket impl in brush-core/src/error.rs
            if path.to_string_lossy().ends_with("brush-core/src/error.rs") {
                let specific_impls = r#"
// Replacement for blanket impl
macro_rules! impl_from_error {
    ($t:ty) => {
        impl From<$t> for Error {
            fn from(err: $t) -> Self {
                Self {
                    kind: ErrorKind::from(err),
                    fatal: false,
                }
            }
        }
    }
}

impl_from_error!(std::io::Error);
impl_from_error!(std::num::ParseIntError);
impl_from_error!(std::num::TryFromIntError);
impl_from_error!(std::string::FromUtf8Error);
impl_from_error!(std::str::Utf8Error);
impl_from_error!(fancy_regex::Error);
impl_from_error!(std::fmt::Error);
impl_from_error!(tokio::task::JoinError);
impl_from_error!(std::time::SystemTimeError);
impl_from_error!(crate::brush_core::sys::PlatformError);
impl_from_error!(crate::brush_core::arithmetic::EvalError);
impl_from_error!(crate::brush_core::parser::WordParseError);
impl_from_error!(crate::brush_core::parser::TestCommandParseError);
impl_from_error!(crate::brush_core::parser::BindingParseError);
impl_from_error!(ErrorKind);
"#;
                new_content = new_content.replace(
                    "impl<T> From<T> for Error",
                    &format!("{}\n#[cfg(any())] impl<T> From<T> for Error", specific_impls)
                );
            }

            // 5. Patch `mod name;` with absolute paths
            // Regex: ^\s*(pub(?:\([^)]+\))?\s+)?mod\s+(\w+)\s*;
            let mod_re = Regex::new(r"(?m)^\s*((?:pub(?:\([^)]+\))?\s+)*)mod\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*;").unwrap();
            
            new_content = mod_re.replace_all(&new_content, |caps: &regex::Captures| {
                let vis = &caps[1];
                let mod_name = &caps[2];
                
                // Determine potential paths
                let parent_dir = path.parent().unwrap();
                let file_stem = path.file_stem().unwrap().to_str().unwrap();
                
                let mut search_dirs = vec![];
                if file_stem == "lib" || file_stem == "mod" {
                    search_dirs.push(parent_dir.to_path_buf());
                } else {
                    search_dirs.push(parent_dir.join(file_stem));
                }
                
                let mut found_path = None;
                for dir in search_dirs {
                    let p1 = dir.join(format!("{}.rs", mod_name));
                    let p2 = dir.join(mod_name).join("mod.rs");
                    
                    if p1.exists() {
                        found_path = Some(p1);
                        break;
                    }
                    if p2.exists() {
                        found_path = Some(p2);
                        break;
                    }
                }
                
                if let Some(p) = found_path {
                    if mod_name == "refs" {
                        println!("cargo:warning=Resolved refs to: {:?}", p);
                    }
                    format!("#[path = \"{}\"]\n{}mod {};", p.display(), vis, mod_name)
                } else {
                    // If not found, leave it as is (might be a macro-generated module or cfg-ed out)
                    println!("cargo:warning=Module not found: {} in {:?}", mod_name, parent_dir);
                    caps[0].to_string()
                }
            }).to_string();

            // 6. Specific file patches
            if path.to_string_lossy().ends_with("brush-core/src/expansion.rs") {
                 new_content = format!("use std::future::Future;\n{}", new_content);
            }

            if path.to_string_lossy().ends_with("brush-shell/src/entry.rs") {
                 new_content = new_content.replace("async fn run_async", "pub async fn run_async");
                 new_content = new_content.replace("fn try_parse_from", "pub fn try_parse_from");
                 
                 // Add extra builtins support (after crate:: patching has already happened)
                 if new_content.contains("crate::brush_core::Shell::builder()") {
                      // Add global registry at top of file  
                      new_content = format!("use std::collections::HashMap;\npub static mut EXTRA_BUILTINS: Option<HashMap<String, crate::brush_core::builtins::Registration>> = None;\n\n{}", new_content);
                      
                      // Replace the builtin registration to add extra builtins
                      new_content = new_content.replace(
                          "    // Add builtins.\n    let shell = shell.default_builtins(builtin_set).brush_builtins();",
                          "    // Add builtins.\n    let mut shell = shell.default_builtins(builtin_set).brush_builtins();\n    \n    // Add extra builtins from global registry\n    if let Some(extras) = unsafe { EXTRA_BUILTINS.as_ref() } {\n        for (name, reg) in extras {\n            shell = shell.builtin(name.clone(), reg.clone());\n        }\n    }\n    let shell = shell;"
                      );
                  }
                 
                 // Patch MinimalInputBackend instantiation
                 // Match both original and transformed versions
                 let minimal_re = Regex::new(r"(let mut ui = (?:crate::)?brush_interactive::MinimalInputBackend);").unwrap();
                 new_content = minimal_re.replace_all(&new_content, "$1::new();").to_string();
            }
            
            if path.to_string_lossy().ends_with("brush-shell/src/lib.rs") {
                 new_content.push_str("\npub mod embedded;");
            }

            // Patch InputBackend trait and usages
            if new_content.contains("trait InputBackend") {
                 new_content = new_content.replace("fn read_line", "async fn read_line");
            }
            
            // Patch impls and calls
            if (new_content.contains("impl InputBackend") || path.to_string_lossy().contains("interactive")) && !path.to_string_lossy().ends_with("wasm_interactive.rs") {
                 // Make impl methods async
                 // Use regex to avoid double async
                 let async_re = Regex::new(r"(?m)(async\s+)?fn\s+read_line").unwrap();
                 new_content = async_re.replace_all(&new_content, "async fn read_line").to_string();
                 
                 // Patch call sites: .read_line(prompt)? -> .read_line(prompt).await?
                 let call_re = Regex::new(r"\.read_line\(([^)]*)\)\?").unwrap();
                 new_content = call_re.replace_all(&new_content, ".read_line($1).await?").to_string();
            }

            if content != new_content {
                fs::write(path, new_content).unwrap();
            }
        }
    }
}
